import { runScript } from '../../sdk/runner';
const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));
const cheb = (a: number, b: number, c: number, d: number) => Math.max(Math.abs(a - c), Math.abs(b - d));

await runScript(async ({ bot, sdk }) => {
    const cnt = () => sdk.getInventory().reduce((a, i) => a + i.count, 0);
    for (const it of sdk.getInventory()) sdk.sendDropItem(it.slot);
    await sleep(200);
    const out: any[] = [];
    for (const type of ['copper', 'tin', 'iron']) {
        // find an available rock of this type and stand next to it
        const st = sdk.getState()!;
        const rock = st.nearbyLocs.filter(l => new RegExp(type + ' ore', 'i').test(l.name))
            .sort((a, b) => a.distance - b.distance)[0];
        if (!rock) { out.push({ type, err: 'none' }); continue; }
        await bot.walkTo(rock.x, rock.z, 1);
