const locs = await sdk.scanNearbyLocs(70);
const trees = locs.filter(l=>/^tree$/i.test(l.name)).map(l=>({x:l.x,z:l.z}));
// find tile maximizing number of trees with chebyshev-ish adjacency (dist<=1 in x&z)
const cand = {};
for (const t of trees) for (let dx=-1;dx<=1;dx++) for (let dz=-1;dz<=1;dz++){
  const k = `${t.x+dx},${t.z+dz}`; cand[k]=(cand[k]||0)+1;
}
const best = Object.entries(cand).sort((a,b)=>b[1]-a[1]).slice(0,12);
// also count trees within 3 tiles of each tree
const dens = trees.map(t=>({t:`${t.x},${t.z}`, n: trees.filter(o=>Math.abs(o.x-t.x)<=3&&Math.abs(o.z-t.z)<=3).length})).sort((a,b)=>b.n-a.n).slice(0,10);
return { totalTrees: trees.length, bestAdjTiles: best, densest3: dens };

async function measure(pat, x, z, secs, label) {
  await bot.walkTo(x, z, 1);
