  while (Date.now()-t0 < secs*1000) {
    const st = sdk.getState();
    if (st.inventory.length >= 26) for (const l of st.inventory.filter(i=>/logs$/i.test(i.name))) await sdk.sendDropItem(l.slot);
    const tr = st.nearbyLocs.filter(l=>pat.test(l.name)&&l.optionsWithIndex.some(o=>/chop/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
    if (!tr) { await bot.walkTo(x,z,1); continue; }
    const r = await bot.chopTree(tr); tries++; if (r&&r.success) n++;
  }
  const raw = sdk.getSkillXp('Woodcutting')-x0, s=(Date.now()-t0)/1000;
  return { label, logs:n, tries, raw, secs:+s.toFixed(1), scorePerMin: +(raw/s*60/200).toFixed(1) };
}
