let last = b, lastT = t0;
while (Date.now() - t0 < 150000) {
  const pl = sdk.getState().player;
  if (pl.hp === 0) {
    marks.push('died@'+Math.round((Date.now()-t0)/1000));
    await bot.dismissBlockingUI().catch(()=>{});
    await sdk.waitForTicks(5);
    // respawned in Lumbridge - keep training on whatever is close
    while (Date.now() - t0 < 150000) {
      try { await bot.attackNpc(/^(Rat|Man|Woman|Goblin|Cow)$/i); } catch(e) { await sdk.waitForTicks(1); }
    }
    break;
  }
  try { await bot.attackNpc(/warrior/i); } catch(e) { await sdk.waitForTicks(1); }
  if (Date.now() - lastT >= 15000) { const cur = sdk.getSkillXp('Attack'); marks.push(Math.round((cur-last)/200*(15000/(Date.now()-lastT)))); last = cur; lastT = Date.now(); }
}
const g = sdk.getSkillXp('Attack') - b, secs = (Date.now()-t0)/1000;
return { gained: g, secs, avgScore: g/(secs/60)/200, marks, atk: sdk.getSkill('Attack').level };
